sksl:
uniform shader image;
uniform shader blurred;
uniform float2 size;
uniform float time;
uniform float blur;
uniform float mode;
uniform float gain;
uniform float amount;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float4 b = float4(blurred.eval(coord));
    float4 r = b;
    if (mode > 0.5 && mode < 1.5) r = float4(c.rgb * (b.a / max(c.a, 0.0001)), b.a);
    else if (mode > 1.5) r = float4(unp(b) * c.a, c.a);
    r = float4(r.rgb * gain, r.a);
    return fin(c, mix(c, r, amount), opacity);
}
